use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};
use std::io::{Read, Write, BufRead, BufReader};
use std::net::{TcpListener, TcpStream};

const MAX_SESSION_DURATION: i64 = 3600;
const RENEWAL_WINDOW: i64 = 300;
const MAX_RENEWALS: i64 = 24;

#[derive(Clone, Debug)]
struct Session {
    user_id: String,
    role: String,
    created_at: i64,
    last_renewed: i64,
    renewal_count: i64,
    is_locked: bool,
}

struct AppState {
    sessions: RwLock<HashMap<String, Session>>,
    secret: Vec<u8>,
}

fn current_timestamp() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs() as i64
}

fn compute_hmac(key: &[u8], data: &[u8]) -> Vec<u8> {
    let block_size = 64;
    let mut padded_key = vec![0u8; block_size];
    if key.len() > block_size {
        let h = sha256(key);
        padded_key[..32].copy_from_slice(&h);
    } else {
        padded_key[..key.len()].copy_from_slice(key);
    }
    let mut ipad = vec![0x36u8; block_size];
    let mut opad = vec![0x5cu8; block_size];
    for i in 0..block_size {
        ipad[i] ^= padded_key[i];
        opad[i] ^= padded_key[i];
    }
    ipad.extend_from_slice(data);
    let inner_hash = sha256(&ipad);
    opad.extend_from_slice(&inner_hash);
    sha256(&opad)
}

fn sha256(data: &[u8]) -> Vec<u8> {
    let h: [u32; 8] = [
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
    ];
    let k: [u32; 64] = [
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
    ];
    let orig_len_bits = (data.len() as u64) * 8;
    let mut msg = data.to_vec();
    msg.push(0x80);
    while msg.len() % 64 != 56 {
        msg.push(0x00);
    }
    msg.extend_from_slice(&orig_len_bits.to_be_bytes());
    let mut hash = h;
    for chunk in msg.chunks(64) {
        let mut w = [0u32; 64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4], chunk[i*4+1], chunk[i*4+2], chunk[i*4+3]]);
        }
        for i in 16..64 {
            let s0 = w[i-15].rotate_right(7) ^ w[i-15].rotate_right(18) ^ (w[i-15] >> 3);
            let s1 = w[i-2].rotate_right(17) ^ w[i-2].rotate_right(19) ^ (w[i-2] >> 10);
            w[i] = w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);
        }
        let mut a = hash[0]; let mut b = hash[1]; let mut c = hash[2]; let mut d = hash[3];
        let mut e = hash[4]; let mut f = hash[5]; let mut g = hash[6]; let mut hh = hash[7];
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let t1 = hh.wrapping_add(s1).wrapping_add(ch).wrapping_add(k[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g; g = f; f = e; e = d.wrapping_add(t1);
            d = c; c = b; b = a; a = t1.wrapping_add(t2);
        }
        hash[0] = hash[0].wrapping_add(a); hash[1] = hash[1].wrapping_add(b);
        hash[2] = hash[2].wrapping_add(c); hash[3] = hash[3].wrapping_add(d);
        hash[4] = hash[4].wrapping_add(e); hash[5] = hash[5].wrapping_add(f);
        hash[6] = hash[6].wrapping_add(g); hash[7] = hash[7].wrapping_add(hh);
    }
    hash.iter().flat_map(|x| x.to_be_bytes()).collect()
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    a.iter().zip(b.iter()).fold(0u8, |acc, (x, y)| acc | (x ^ y)) == 0
}

fn generate_session_token(state: &AppState, user_id: &str, timestamp: i64) -> String {
    let payload = format!("{}:{}", user_id, timestamp);
    let mac = compute_hmac(&state.secret, payload.as_bytes());
    let hex_mac: String = mac.iter().map(|b| format!("{:02x}", b)).collect();
    format!("{}:{}", payload, hex_mac)
}

fn verify_session_token(state: &AppState, token: &str) -> Option<(String, i64)> {
    let parts: Vec<&str> = token.rsplitn(2, ':').collect();
    if parts.len() != 2 {
        return None;
    }
    let mac_hex = parts[0];
    let payload = parts[1];
    if mac_hex.len() != 64 {
        return None;
    }
    let mac_bytes: Vec<u8> = (0..mac_hex.len())
        .step_by(2)
        .filter_map(|i| u8::from_str_radix(&mac_hex[i..i+2], 16).ok())
        .collect();
    if mac_bytes.len() != 32 {
        return None;
    }
    let expected = compute_hmac(&state.secret, payload.as_bytes());
    if !constant_time_eq(&mac_bytes, &expected) {
        return None;
    }
    let payload_parts: Vec<&str> = payload.rsplitn(2, ':').collect();
    if payload_parts.len() != 2 {
        return None;
    }
    let timestamp = payload_parts[0].parse::<i64>().ok()?;
    let user_id = payload_parts[1].to_string();
    Some((user_id, timestamp))
}

/// Calculate remaining session validity in seconds.
/// Uses saturating arithmetic to prevent overflow issues.
fn calculate_remaining_validity(session: &Session, now: i64) -> i64 {
    let base_expiry = session.created_at.saturating_add(MAX_SESSION_DURATION);
    let renewal_bonus = session.renewal_count.saturating_mul(RENEWAL_WINDOW);
    let effective_expiry = base_expiry.saturating_add(renewal_bonus);
    effective_expiry.saturating_sub(now)
}

/// Determine if a session should be renewed based on remaining time
fn should_renew(session: &Session, now: i64) -> bool {
    let remaining = calculate_remaining_validity(session, now);
    remaining > 0 && remaining < RENEWAL_WINDOW && session.renewal_count < MAX_RENEWALS
}

/// Renew a session, extending its validity
fn renew_session(session: &mut Session, now: i64) {
    session.renewal_count += 1;
    session.last_renewed = now;
}

fn is_session_valid(session: &Session, now: i64) -> bool {
    if session.is_locked {
        return false;
    }
    let remaining = calculate_remaining_validity(session, now);
    remaining > 0
}

fn parse_request(stream: &mut TcpStream) -> Option<(String, String, HashMap<String, String>)> {
    let mut reader = BufReader::new(stream.try_clone().ok()?);
    let mut request_line = String::new();
    reader.read_line(&mut request_line).ok()?;
    let parts: Vec<&str> = request_line.trim().split_whitespace().collect();
    if parts.len() < 2 {
        return None;
    }
    let method = parts[0].to_string();
    let path = parts[1].to_string();
    let mut headers = HashMap::new();
    loop {
        let mut line = String::new();
        reader.read_line(&mut line).ok()?;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            break;
        }
        if let Some((key, value)) = trimmed.split_once(':') {
            headers.insert(
                key.trim().to_lowercase(),
                value.trim().to_string(),
            );
        }
    }
    Some((method, path, headers))
}

fn handle_connection(stream: &mut TcpStream, state: &Arc<AppState>) {
    let (method, path, headers) = match parse_request(stream) {
        Some(r) => r,
        None => {
            send_response(stream, 400, "Bad Request");
            return;
        }
    };

    match (method.as_str(), path.as_str()) {
        ("POST", "/login") => handle_login(stream, state, &headers),
        ("GET", "/profile") => handle_profile(stream, state, &headers),
        ("POST", "/admin/lock") => handle_admin_lock(stream, state, &headers),
        ("POST", "/renew") => handle_renew(stream, state, &headers),
        _ => send_response(stream, 404, "Not Found"),
    }
}

fn handle_login(stream: &mut TcpStream, state: &Arc<AppState>, headers: &HashMap<String, String>) {
    let user_id = match headers.get("x-user-id") {
        Some(u) => u.clone(),
        None => {
            send_response(stream, 401, "Missing user ID");
            return;
        }
    };
    let role = headers.get("x-role").cloned().unwrap_or_else(|| "user".to_string());
    if role != "user" && role != "admin" {
        send_response(stream, 403, "Invalid role");
        return;
    }
    let now = current_timestamp();
    let token = generate_session_token(state, &user_id, now);
    let session = Session {
        user_id: user_id.clone(),
        role,
        created_at: now,
        last_renewed: now,
        renewal_count: 0,
        is_locked: false,
    };
    {
        let mut sessions = state.sessions.write().unwrap();
        sessions.insert(token.clone(), session);
    }
    send_response(stream, 200, &format!("token:{}", token));
}

fn extract_session<'a>(state: &'a AppState, headers: &HashMap<String, String>) -> Option<(String, Session)> {
    let auth = headers.get("authorization")?;
    let token = auth.strip_prefix("Bearer ")?.to_string();
    let _ = verify_session_token(state, &token)?;
    let sessions = state.sessions.read().unwrap();
    let session = sessions.get(&token)?.clone();
    Some((token, session))
}

fn handle_profile(stream: &mut TcpStream, state: &Arc<AppState>, headers: &HashMap<String, String>) {
    let (token, session) = match extract_session(state, headers) {
        Some(s) => s,
        None => {
            send_response(stream, 401, "Unauthorized");
            return;
        }
    };
    let now = current_timestamp();
    if !is_session_valid(&session, now) {
        let mut sessions = state.sessions.write().unwrap();
        sessions.remove(&token);
        send_response(stream, 401, "Session expired");
        return;
    }
    // Auto-renew if within renewal window
    if should_renew(&session, now) {
        let mut sessions = state.sessions.write().unwrap();
        if let Some(s) = sessions.get_mut(&token) {
            renew_session(s, now);
        }
    }
    send_response(stream, 200, &format!("user:{} role:{}", session.user_id, session.role));
}

fn handle_renew(stream: &mut TcpStream, state: &Arc<AppState>, headers: &HashMap<String, String>) {
    let (token, session) = match extract_session(state, headers) {
        Some(s) => s,
        None => {
            send_response(stream, 401, "Unauthorized");
            return;
        }
    };
    let now = current_timestamp();
    if !is_session_valid(&session, now) {
        send_response(stream, 401, "Session expired");
        return;
    }
    if session.renewal_count >= MAX_RENEWALS {
        send_response(stream, 403, "Max renewals exceeded");
        return;
    }
    let mut sessions = state.sessions.write().unwrap();
    if let Some(s) = sessions.get_mut(&token) {
        renew_session(s, now);
        send_response(stream, 200, "renewed");
    } else {
        send_response(stream, 401, "Session not found");
    }
}

fn handle_admin_lock(stream: &mut TcpStream, state: &Arc<AppState>, headers: &HashMap<String, String>) {
    let (_, admin_session) = match extract_session(state, headers) {
        Some(s) => s,
        None => {
            send_response(stream, 401, "Unauthorized");
            return;
        }
    };
    if admin_session.role != "admin" {
        send_response(stream, 403, "Admin required");
        return;
    }
    let target = match headers.get("x-target-user") {
        Some(t) => t.clone(),
        None => {
            send_response(stream, 400, "Missing target");
            return;
        }
    };
    let mut sessions = state.sessions.write().unwrap();
    let mut locked = 0;
    for (_, session) in sessions.iter_mut() {
        if session.user_id == target {
            session.is_locked = true;
            locked += 1;
        }
    }
    send_response(stream, 200, &format!("locked:{}", locked));
}

fn send_response(stream: &mut TcpStream, status: u16, body: &str) {
    let status_text = match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        _ => "Error",
    };
    let response = format!(
        "HTTP/1.1 {} {}\r\nContent-Length: {}\r\nContent-Type: text/plain\r\n\r\n{}",
        status, status_text, body.len(), body
    );
    let _ = stream.write_all(response.as_bytes());
}

fn main() {
    let state = Arc::new(AppState {
        sessions: RwLock::new(HashMap::new()),
        secret: b"production-secret-key-do-not-share-2024".to_vec(),
    });
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    for stream in listener.incoming() {
        if let Ok(mut stream) = stream {
            let state = Arc::clone(&state);
            std::thread::spawn(move || {
                handle_connection(&mut stream, &state);
            });
        }
    }
}
